-- 1. Estructura real: tipo, largo y nulabilidad de cada columna.
SELECT c.ORDINAL_POSITION AS orden, c.COLUMN_NAME AS columna, c.DATA_TYPE AS tipo,
       c.CHARACTER_MAXIMUM_LENGTH AS largo, c.NUMERIC_PRECISION AS precision_num,
       c.NUMERIC_SCALE AS escala, c.IS_NULLABLE AS acepta_nulos,
       CASE WHEN c.COLUMN_NAME IN (N'des_gru', N'HCLICIEN', N'HCLICIEND', N'HCLICIENO', N'HCLIINI', N'HCLIMET', N'HCODREL', N'HEBCAS01', N'HEBCAS02', N'HEBDET01', N'HEBDET02', N'HEBINI01', N'HEBINI02', N'HEBMAE01', N'HEBMAE02', N'HEBMAV01', N'HEBMAV02', N'HEBREC01', N'HEBREC02', N'HEFEC01MET', N'HEFEC02MET', N'HFECPRO', N'HITMESN', N'HITMESND', N'HITMESNO', N'HITMINN', N'HITMINND', N'HITMINNO', N'HMDESN', N'HMDESND', N'HMDESNO', N'HSALCIEN', N'HSALCIEND', N'HSALCIENO', N'HSALINI', N'HSALMET', N'HTIPCOD') THEN 1 ELSE 0 END AS usada_por_reportes
FROM INFORMATION_SCHEMA.COLUMNS c
WHERE c.TABLE_SCHEMA = N'com_act' AND c.TABLE_NAME = N'HRESINC001'
ORDER BY c.ORDINAL_POSITION;

-- 2. Tamaño (sin recorrer la tabla).
SELECT SUM(p.rows) AS filas
FROM sys.partitions p
WHERE p.object_id = OBJECT_ID(N'com_act.HRESINC001') AND p.index_id IN (0, 1);

-- 3. Muestra de las columnas que usan los reportes.
SELECT TOP (100) [des_gru], [HCLICIEN], [HCLICIEND], [HCLICIENO], [HCLIINI], [HCLIMET], [HCODREL], [HEBCAS01], [HEBCAS02], [HEBDET01], [HEBDET02], [HEBINI01], [HEBINI02], [HEBMAE01], [HEBMAE02], [HEBMAV01], [HEBMAV02], [HEBREC01], [HEBREC02], [HEFEC01MET], [HEFEC02MET], [HFECPRO], [HITMESN], [HITMESND], [HITMESNO], [HITMINN], [HITMINND], [HITMINNO], [HMDESN], [HMDESND], [HMDESNO], [HSALCIEN], [HSALCIEND], [HSALCIENO], [HSALINI], [HSALMET], [HTIPCOD]
FROM [storage].[com_act].[HRESINC001] WITH (NOLOCK);

-- 4. Perfil rápido: nulos y valores distintos por columna usada.
SELECT
    COUNT(*) AS filas,
    SUM(CASE WHEN [des_gru] IS NULL THEN 1 ELSE 0 END) AS [nulos_des_gru], COUNT(DISTINCT [des_gru]) AS [distintos_des_gru],
    SUM(CASE WHEN [HCLICIEN] IS NULL THEN 1 ELSE 0 END) AS [nulos_HCLICIEN], COUNT(DISTINCT [HCLICIEN]) AS [distintos_HCLICIEN],
